137	
138	    sr = x_src[list(idx_src)]
139	    sc = np.dot(sr, x_tgt.T)
140	    similarities = 2 * sc
141	    sc2 = np.zeros(x_tgt.shape[0])
142	    for i in range(0, x_tgt.shape[0], bsz):
143	        j = min(i + bsz, x_tgt.shape[0])
144	        sc_batch = np.dot(x_tgt[i:j, :], x_src.T)
145	        dotprod = np.partition(sc_batch, -k, axis=1)[:, -k:]
146	        sc2[i:j] = np.mean(dotprod, axis=1)
147	    similarities -= sc2[np.newaxis, :]
148	
149	    nn = np.argmax(similarities, axis=1).tolist()
150	    correct = 0.0
151	    for k in range(0, len(lexicon)):
152	        if nn[k] in lexicon[idx_src[k]]:
