38: void DenseMatrix::uniformThread(real a, int block, int32_t seed) {
39:   std::minstd_rand rng(block + seed);
40:   std::uniform_real_distribution<> uniform(-a, a);
41:   int64_t blockSize = (m_ * n_) / 10;
42:   for (int64_t i = blockSize * block;
43:        i < (m_ * n_) && i < blockSize * (block + 1);
44:        i++) {
45:     data_[i] = uniform(rng);
46:   }
47: }
