49: void DenseMatrix::uniform(real a, unsigned int thread, int32_t seed) {
50:   if (thread > 1) {
51:     std::vector<std::thread> threads;
52:     for (int i = 0; i < thread; i++) {
53:       threads.push_back(std::thread([=]() { uniformThread(a, i, seed); }));
54:     }
55:     for (int32_t i = 0; i < threads.size(); i++) {
56:       threads[i].join();
57:     }
58:   } else {
59:     // webassembly can't instantiate `std::thread`
60:     uniformThread(a, 0, seed);
61:   }
62: }
