64: void DenseMatrix::multiplyRow(const Vector& nums, int64_t ib, int64_t ie) {
65:   if (ie == -1) {
66:     ie = m_;
67:   }
68:   assert(ie <= nums.size());
69:   for (auto i = ib; i < ie; i++) {
70:     real n = nums[i - ib];
71:     if (n != 0) {
72:       for (auto j = 0; j < n_; j++) {
73:         at(i, j) *= n;
74:       }
75:     }
76:   }
77: }
