79: void DenseMatrix::divideRow(const Vector& denoms, int64_t ib, int64_t ie) {
80:   if (ie == -1) {
81:     ie = m_;
82:   }
83:   assert(ie <= denoms.size());
84:   for (auto i = ib; i < ie; i++) {
85:     real n = denoms[i - ib];
86:     if (n != 0) {
87:       for (auto j = 0; j < n_; j++) {
88:         at(i, j) /= n;
89:       }
90:     }
91:   }
