94: real DenseMatrix::l2NormRow(int64_t i) const {
95:   auto norm = 0.0;
96:   for (auto j = 0; j < n_; j++) {
97:     norm += at(i, j) * at(i, j);
98:   }
99:   if (std::isnan(norm)) {
100:     throw EncounteredNaNError();
101:   }
102:   return std::sqrt(norm);
103: }
