112: real DenseMatrix::dotRow(const Vector& vec, int64_t i) const {
113:   assert(i >= 0);
114:   assert(i < m_);
115:   assert(vec.size() == n_);
116:   real d = 0.0;
117:   for (int64_t j = 0; j < n_; j++) {
118:     d += at(i, j) * vec[j];
119:   }
120:   if (std::isnan(d)) {
121:     throw EncounteredNaNError();
122:   }
123:   return d;
